<script setup lang="ts">
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, ref, nextTick } from 'vue';
import { Plus, ArrowLeft, MapPin, CalendarDays, Users, ReceiptText, Pencil, CheckCheck, Banknote, LockKeyhole, CircleX, Check } from 'lucide-vue-next';
import TravelLayout from '@/layouts/TravelLayout.vue';
import { googleMapsUrl } from '@/lib/maps';
import { calculateShares } from '@/lib/splits';
type Member={id:number;user:{name:string}};
type Expense={id:number;title:string;merchant:string;status:string;version:number;total_minor:number;incurred_at:string;category_id:number;split_method:string;category:{name:string};cancellation_reason:string|null;payments:{trip_member_id:number;amount_minor:number}[];allocations:{trip_member_id:number;amount_minor:number;basis_value:string|null;expense_item_id:number|null}[];items:{id:number;description:string;line_total_minor:number}[];receipts:{id:number;processing_status:string}[]};
const props=defineProps<{trip:{id:number;name:string;destination:string;description:string;starts_on:string;ends_on:string;timezone:string;currency_code:string;members:Member[];expenses:Expense[];itinerary_items:{id:number;title:string;location:string;starts_at:string;ends_at:string}[];settlements:{id:number;expense_id:number|null;from_member_id:number;to_member_id:number;amount_minor:number;status:string}[]};categories:{id:number;name:string}[];balances:{member_id:number;name:string;net_minor:number}[];isOrganizer:boolean;currentMemberId:number;invitationUrl:string|null;expenseShares:Record<number,{member_id:number;share_minor:number;covered_minor:number;remaining_minor:number}[]>}>();
const tab=ref('expenses'); const adding=ref(false); const statusFilter=ref('all'); const reason=ref<Record<number,string>>({});
const cancellingId=ref<number|null>(null); const voidPayments=ref<Record<number,boolean>>({});
const actionErrors=ref<Record<number,string>>({}); const busyId=ref<number|null>(null);
const shareConfirm=ref<{expenseId:number;memberId:number}|null>(null);
const paymentSource=ref('new');
function canConfirmShare(e:Expense){return props.isOrganizer || (props.expenseShares[e.id]??[]).some(s=>s.member_id===props.currentMemberId&&s.covered_minor>s.share_minor);}
function existingRepayments(e:Expense,memberId:number){const creditors=(props.expenseShares[e.id]??[]).filter(s=>s.covered_minor>s.share_minor&&(props.isOrganizer||s.member_id===props.currentMemberId)).map(s=>s.member_id);return props.trip.settlements.filter(s=>s.expense_id===null&&s.from_member_id===memberId&&creditors.includes(s.to_member_id)&&['pending','confirmed'].includes(s.status));}
function openShareConfirmation(e:Expense,memberId:number){shareConfirm.value={expenseId:e.id,memberId};paymentSource.value=String(existingRepayments(e,memberId)[0]?.id??'new');actionErrors.value[e.id]='';}
function confirmableAmount(e:Expense,memberId:number){const rows=props.expenseShares[e.id]??[];const remaining=rows.find(s=>s.member_id===memberId)?.remaining_minor??0;const available=rows.filter(s=>props.isOrganizer||s.member_id===props.currentMemberId).reduce((sum,s)=>sum+Math.max(0,s.covered_minor-s.share_minor),0);const existing=existingRepayments(e,memberId).find(s=>String(s.id)===paymentSource.value);if(existing){const credit=rows.find(s=>s.member_id===existing.to_member_id);return Math.min(remaining,existing.amount_minor,Math.max(0,(credit?.covered_minor??0)-(credit?.share_minor??0)));}return Math.min(remaining,available);}
const editingId=ref<number|null>(null); const editingVersion=ref(1); const editor=ref<HTMLFormElement|null>(null);
const minor=(value:string|number)=>{const s=String(value).trim();if(!/^\d+(\.\d{1,2})?$/.test(s))return -1;const [whole,fraction='']=s.split('.');return Number(whole)*100+Number(fraction.padEnd(2,'0'));};
const money=(amount:number)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:props.trip.currency_code}).format(amount/100);
const name=(id:number)=>props.trip.members.find(m=>m.id===id)?.user.name??'Traveler';
const date=(value:string)=>new Intl.DateTimeFormat('en',{dateStyle:'medium',timeStyle:'short',timeZone:props.trip.timezone}).format(new Date(value));
const shown=computed(()=>props.trip.expenses.filter(e=>statusFilter.value==='all'||e.status===statusFilter.value));
const spent=computed(()=>props.trip.expenses.filter(e=>['completed','closed'].includes(e.status)).reduce((s,e)=>s+e.total_minor,0));
const today=new Intl.DateTimeFormat('en-CA',{timeZone:props.trip.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const expense=useForm({title:'',merchant:'',incurred_at:today,category_id:props.categories[0]?.id??'',amount:'',split_method:'equal',people:props.trip.members.map(m=>({id:m.id,selected:true as boolean,value:'1'})),payers:[{id:props.currentMemberId,amount:''}],items:[{description:'',amount:'',member_ids:[] as number[]}]});
const splitPreview=computed(()=>{
    try {
        let amounts:Record<number,number>={};
        if(expense.split_method==='itemized') {
            if(expense.items.reduce((sum,item)=>sum+minor(item.amount),0)!==minor(expense.amount)) throw new Error('Receipt line totals must match the expense total.');
            for(const item of expense.items) {
                const shares=calculateShares(minor(item.amount),'equal',item.member_ids.map(id=>({id,weight:1})));
                for(const [id,amount] of Object.entries(shares)) amounts[Number(id)]=(amounts[Number(id)]??0)+amount;
            }
        } else amounts=calculateShares(minor(expense.amount),expense.split_method,expense.people.filter(p=>p.selected).map(p=>({id:p.id,weight:['exact','percentage'].includes(expense.split_method)?minor(p.value):Number(p.value)})));
        return {amounts,error:''};
    } catch(error) {return {amounts:{} as Record<number,number>,error:error instanceof Error?error.message:'Check the split values.'};}
});
function newExpense(){expense.reset();expense.clearErrors();editingId.value=null;adding.value=true;}
async function editExpense(e:Expense){
    expense.clearErrors();editingId.value=e.id;editingVersion.value=e.version;
    expense.title=e.title;expense.merchant=e.merchant??'';expense.incurred_at=e.incurred_at;expense.category_id=e.category_id;expense.amount=(e.total_minor/100).toFixed(2);expense.split_method=e.split_method;
    expense.people=props.trip.members.map(m=>{const allocations=e.allocations.filter(a=>a.trip_member_id===m.id);const basis=Number(allocations[0]?.basis_value??1);return {id:m.id,selected:allocations.length>0,value:e.split_method==='exact'?(allocations.reduce((sum,a)=>sum+a.amount_minor,0)/100).toFixed(2):e.split_method==='percentage'?(basis/100).toFixed(2):String(basis)};});
    const paid:Record<number,number>={};for(const p of e.payments)paid[p.trip_member_id]=(paid[p.trip_member_id]??0)+p.amount_minor;
    expense.payers=Object.entries(paid).map(([id,amount])=>({id:Number(id),amount:(amount/100).toFixed(2)}));
    expense.items=e.items.length?e.items.map(item=>({description:item.description,amount:(item.line_total_minor/100).toFixed(2),member_ids:e.allocations.filter(a=>a.expense_item_id===item.id).map(a=>a.trip_member_id)})):[{description:'',amount:'',member_ids:[]}];
    adding.value=true;await nextTick();editor.value?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});
}
function saveExpense(){
    expense.transform(d=>({version:editingVersion.value,title:d.title,merchant:d.merchant,incurred_at:d.incurred_at,category_id:d.category_id,total_minor:minor(d.amount),split_method:d.split_method,payments:d.payers.filter(p=>p.amount!=='').map(p=>({trip_member_id:p.id,amount_minor:minor(p.amount)})),allocations:d.people.filter(p=>p.selected).map(p=>({trip_member_id:p.id,weight:d.split_method==='equal'?1:['exact','percentage'].includes(d.split_method)?minor(p.value):Number(p.value)})),items:d.split_method==='itemized'?d.items.map(i=>({description:i.description,amount_minor:minor(i.amount),member_ids:i.member_ids})):[]}));
    const options={preserveScroll:true,onSuccess:()=>{adding.value=false;editingId.value=null;expense.reset();}};
    if(editingId.value)expense.patch(`/trips/${props.trip.id}/expenses/${editingId.value}`,options);else expense.post(`/trips/${props.trip.id}/expenses`,options);
}
const itinerary=useForm({title:'',location:'',description:'',starts_at:'',ends_at:''});
const settlement=useForm({to_member_id:props.trip.members.find(m=>m.id!==props.currentMemberId)?.id??'',amount:'',payment_method:'gcash'});
const payment=useForm({expense_id:0,trip_member_id:props.currentMemberId,amount:'',version:1});
const receipt=useForm<{receipt:File|null}>({receipt:null});
function status(e:Expense,target:string){
    actionErrors.value[e.id]='';busyId.value=e.id;
    router.patch(`/trips/${props.trip.id}/expenses/${e.id}/status`,{status:target,version:e.version,reason:reason.value[e.id]??null,void_payments:voidPayments.value[e.id]??false},{preserveScroll:true,onError:errors=>actionErrors.value[e.id]=Object.values(errors).join(' '),onSuccess:()=>{cancellingId.value=null;if(target==='cancelled')statusFilter.value='all';},onFinish:()=>busyId.value=null});
}
function markSharePaid(e:Expense,memberId:number){
    actionErrors.value[e.id]='';busyId.value=e.id;
    router.post(`/trips/${props.trip.id}/expenses/${e.id}/shares/paid`,{member_id:memberId,version:e.version,settlement_id:paymentSource.value==='new'?null:Number(paymentSource.value),new_payment:paymentSource.value==='new'},{preserveScroll:true,onError:errors=>actionErrors.value[e.id]=Object.values(errors).join(' '),onSuccess:()=>shareConfirm.value=null,onFinish:()=>busyId.value=null});
}
function upload(event:Event,e:Expense){receipt.receipt=(event.target as HTMLInputElement).files?.[0]??null;if(receipt.receipt)receipt.post(`/trips/${props.trip.id}/expenses/${e.id}/receipts`,{preserveScroll:true,onSuccess:()=>receipt.reset()});}
</script>
<template>
<Head :title="trip.name"/><TravelLayout>
 <Link href="/dashboard" class="row muted" style="margin-bottom:24px"><ArrowLeft :size="14"/> All trips</Link>
 <div class="page-heading"><div><p class="eyebrow"><a :href="googleMapsUrl(trip.destination)" target="_blank" rel="noopener noreferrer" class="row" style="text-decoration:underline;text-underline-offset:4px" title="Open destination in Google Maps"><MapPin :size="14"/> {{ trip.destination }} ↗</a></p><h1>{{ trip.name }}</h1><p class="row muted" style="margin-top:14px"><CalendarDays :size="16"/> {{ trip.starts_on }} — {{ trip.ends_on }} <Users :size="16"/> {{ trip.members.length }} travelers</p></div><button v-if="isOrganizer" class="btn secondary" @click="router.post(`/trips/${trip.id}/invitations`,{},{preserveScroll:true})">Invite friends</button></div>
 <div v-if="invitationUrl" class="card" style="margin-bottom:24px"><label class="field">Invitation link · valid for 7 days<input :value="invitationUrl" readonly @focus="($event.target as HTMLInputElement).select()"/></label></div>
 <div class="stats"><div class="stat featured"><p>Trip spending</p><strong>{{ money(spent) }}</strong><small>Completed and closed expenses</small></div><div class="stat"><p>Recorded expenses</p><strong>{{ trip.expenses.length }}</strong><small>{{ trip.expenses.filter(e=>e.status==='open').length }} awaiting completion</small></div><div class="stat"><p>Your balance</p><strong>{{ money(balances.find(b=>b.member_id===currentMemberId)?.net_minor??0) }}</strong><small>Positive: receive · Negative: owe</small></div></div>
 <div class="tabs"><button v-for="item in ['expenses','itinerary','balances']" :key="item" :class="{active:tab===item}" @click="tab=item">{{ item }}</button></div>
 <section v-if="tab==='expenses'">
 <div class="row spread" style="margin-bottom:20px"><div class="row"><h2>Shared expenses</h2><select v-model="statusFilter" aria-label="Filter expenses" class="filter"><option value="all">All statuses</option><option v-for="s in ['open','completed','closed','cancelled']" :key="s">{{ s }}</option></select></div><button class="btn" @click="newExpense"><Plus :size="16"/> Add expense</button></div>
 <form v-if="adding" ref="editor" class="card form-grid" style="margin-bottom:24px" @submit.prevent="saveExpense"><h2 class="full">{{ editingId ? 'Edit expense & assigned shares' : 'Record a shared expense' }}</h2><label class="field">Title<input v-model="expense.title" required placeholder="Dinner by the beach"/></label><label class="field">Category<select v-model="expense.category_id" required><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label class="field">Total ({{ trip.currency_code }})<input v-model="expense.amount" type="number" min="0.01" max="1000000" step="0.01" required/></label><label class="field">Date<input v-model="expense.incurred_at" type="date" required/></label><label class="field">Merchant<input v-model="expense.merchant"/></label><label class="field">Split method<select v-model="expense.split_method"><option value="equal">Equally</option><option value="exact">Exact amounts</option><option value="percentage">Percentages</option><option value="shares">Shares</option><option value="itemized">By receipt item</option></select></label>
 <div class="full"><h3>Who paid the merchant?</h3><p class="muted">{{ editingId ? 'Recorded payments are preserved. Use Record payment to add another payment.' : 'Leave amounts blank if this expense has not been paid yet.' }}</p><div v-for="(payer,index) in expense.payers" :key="index" class="row" style="margin-top:10px"><label class="field" style="flex:1">Payer<select v-model="payer.id" :disabled="editingId!==null"><option v-for="m in trip.members" :key="m.id" :value="m.id">{{ m.user.name }}</option></select></label><label class="field" style="flex:1">Amount paid<input :disabled="editingId!==null" v-model="payer.amount" type="number" min="0.01" step="0.01"/></label><button v-if="index>0 && !editingId" class="btn secondary" type="button" @click="expense.payers.splice(index,1)">Remove</button></div><button v-if="!editingId" class="btn secondary section-gap" type="button" @click="expense.payers.push({id:currentMemberId,amount:''})">Add another payer</button></div>
 <div v-if="expense.split_method!=='itemized'" class="full"><h3>Who shares this expense?</h3><div v-for="person in expense.people" :key="person.id" class="row" style="margin-top:12px"><label style="flex:1"><input v-model="person.selected" type="checkbox"/> {{ name(person.id) }}</label><label v-if="expense.split_method!=='equal' && person.selected" class="field">{{ expense.split_method==='percentage'?'Percentage':expense.split_method==='exact'?'Amount':'Shares' }}<input v-model="person.value" type="number" min="0" :step="expense.split_method==='shares'?'1':'0.01'" required/></label></div></div>
 <div v-else class="full"><h3>Receipt items</h3><p class="muted">Enter reviewed line totals, including allocated tax or discounts. Each line is split equally among its selected travelers.</p><div v-for="(item,index) in expense.items" :key="index" class="item-entry"><div class="form-grid"><label class="field">Item<input v-model="item.description" required/></label><label class="field">Line total<input v-model="item.amount" type="number" min="0.01" step="0.01" required/></label></div><div class="row" style="margin-top:12px"><label v-for="m in trip.members" :key="m.id"><input v-model="item.member_ids" type="checkbox" :value="m.id"/> {{ m.user.name }}</label><button v-if="expense.items.length>1" type="button" class="btn secondary" @click="expense.items.splice(index,1)">Remove</button></div></div><button type="button" class="btn secondary" @click="expense.items.push({description:'',amount:'',member_ids:[]})">Add receipt line</button></div>
 <div class="full" style="background:#f0f5e9;border-radius:12px;padding:18px" aria-live="polite"><h3>Calculated shares</h3><p v-if="splitPreview.error" class="muted">{{ splitPreview.error }}</p><template v-else><p v-for="(amount,id) in splitPreview.amounts" :key="id" class="row spread" style="margin-top:10px;font-size:14px"><span>{{ name(Number(id)) }}</span><strong>{{ money(amount) }}</strong></p><p class="muted" style="margin-top:12px">Total assigned: {{ money(Object.values(splitPreview.amounts).reduce((sum,amount)=>sum+amount,0)) }}</p></template></div><div class="row full"><button class="btn" :disabled="expense.processing || !!splitPreview.error">{{ editingId ? 'Save changes' : 'Save expense' }}</button><button class="btn secondary" type="button" @click="adding=false">Cancel</button></div></form>
 <div v-if="!shown.length" class="card empty"><ReceiptText :size="36" style="margin:0 auto 16px;color:#839362"/><h2>No expenses here yet.</h2><p class="muted">Record the first shared bill to keep everyone on the same page.</p></div>
 <article v-for="e in shown" :key="e.id" class="card expense-card"><div class="row spread"><div><div class="row"><h3>{{ e.title }}</h3><span class="badge" :class="e.status">{{ e.status }}</span><span v-if="isOrganizer" class="expense-actions" role="group" :aria-label="'Actions for '+e.title">
<button v-if="!['closed','cancelled'].includes(e.status)" class="icon-action" title="Edit expense and shares" aria-label="Edit expense and shares" @click="editExpense(e)"><Pencil :size="16"/></button>
<button v-if="e.status==='open'" class="icon-action" title="Mark merchant bill completed" aria-label="Mark merchant bill completed" :disabled="busyId===e.id" @click="status(e,'completed')"><CheckCheck :size="17"/></button>
<button v-if="e.status==='open'" class="icon-action" title="Record payment to merchant" aria-label="Record payment to merchant" @click="payment.expense_id=e.id;payment.version=e.version;payment.amount=''"><Banknote :size="17"/></button>
<button v-if="e.status==='completed'" class="icon-action" title="Close expense" aria-label="Close expense" :disabled="busyId===e.id" @click="status(e,'closed')"><LockKeyhole :size="16"/></button>
<button v-if="['open','draft','completed'].includes(e.status)" class="icon-action danger-icon" title="Cancel expense" aria-label="Cancel expense" @click="cancellingId=cancellingId===e.id?null:e.id;actionErrors[e.id]=''"><CircleX :size="17"/></button></span></div><p class="muted" style="margin-top:7px">{{ e.category.name }} · {{ e.incurred_at }} <span v-if="e.merchant">· {{ e.merchant }}</span></p></div><strong style="font-size:22px">{{ money(e.total_minor) }}</strong></div><p v-if="e.cancellation_reason" class="muted section-gap">Cancelled: {{ e.cancellation_reason }}</p>
 <details class="section-gap"><summary>Shares, payments & receipts</summary><div class="detail-grid"><div><h3>Assigned shares</h3><div v-for="share in (expenseShares[e.id]??[]).filter(s=>s.share_minor>0)" :key="share.member_id" class="assigned-share">
<div class="row spread muted"><span>{{ name(share.member_id) }}</span><strong>{{ money(share.share_minor) }}</strong></div>
<div v-if="e.status!=='cancelled'" class="row share-status">
<span v-if="share.remaining_minor===0" class="paid-label"><Check :size="14"/> Paid / covered</span>
<template v-else><span class="muted">Remaining {{ money(share.remaining_minor) }}</span><button v-if="canConfirmShare(e)" class="share-paid" :disabled="busyId===e.id" @click="openShareConfirmation(e,share.member_id)"><Check :size="14"/> Mark as paid</button></template>
</div>
<div v-if="shareConfirm?.expenseId===e.id && shareConfirm.memberId===share.member_id" class="share-confirm"><label v-if="existingRepayments(e,share.member_id).length" class="field">Payment to confirm<select v-model="paymentSource"><option v-for="repayment in existingRepayments(e,share.member_id)" :key="repayment.id" :value="String(repayment.id)">Use recorded {{ money(repayment.amount_minor) }} to {{ name(repayment.to_member_id) }} ({{ repayment.status }})</option><option value="new">A separate new payment</option></select></label><p>Confirm {{ money(confirmableAmount(e,share.member_id)) }} received from {{ name(share.member_id) }}{{ isOrganizer ? ' by the traveler(s) who covered this bill' : ' by you' }}. {{ paymentSource==='new' ? 'This records a separate payment already received.' : 'The recorded reimbursement will be applied to this expense, without counting it twice.' }} No money is sent.</p><div class="row"><button class="btn" :disabled="busyId===e.id" @click="markSharePaid(e,share.member_id)">Confirm paid</button><button class="btn secondary" @click="shareConfirm=null">Back</button></div></div>
</div></div><div><h3>Paid to merchant</h3><p v-for="(p,i) in e.payments" :key="i" class="row spread muted">{{ name(p.trip_member_id) }} <strong>{{ money(p.amount_minor) }}</strong></p><p v-if="!e.payments.length" class="muted">No payments recorded.</p></div></div><p v-for="item in e.items" :key="item.id" class="muted">{{ item.description }} · {{ money(item.line_total_minor) }}</p><div class="row section-gap"><a v-for="r in e.receipts" :key="r.id" :href="`/receipts/${r.id}`" class="btn secondary">Download receipt #{{ r.id }}</a></div><label v-if="!['closed','cancelled'].includes(e.status)" class="field section-gap">Attach receipt (JPG, PNG, PDF · up to 10 MB)<input type="file" accept="image/jpeg,image/png,application/pdf" :disabled="receipt.processing" @change="upload($event,e)"/><span class="muted">Stored privately. Automatic reading is not configured yet; enter receipt lines above.</span></label></details>

 <p v-if="actionErrors[e.id]" class="error-box section-gap" role="alert">{{ actionErrors[e.id] }}</p>
 <form v-if="cancellingId===e.id && isOrganizer" class="cancel-panel section-gap" @submit.prevent="status(e,'cancelled')"><h3>Cancel this expense?</h3><label class="field section-gap">Cancellation reason<input v-model="reason[e.id]" maxlength="2000" required placeholder="Why is this expense being cancelled?"/></label><label v-if="e.payments.length" class="void-confirm"><input type="checkbox" v-model="voidPayments[e.id]" required/><span>Void this expense and its linked payments/reimbursements from trip balances. Keep the history. I understand this does not refund money.</span></label><div class="row section-gap"><button class="btn danger" :disabled="busyId===e.id || !reason[e.id]?.trim() || (e.payments.length>0&&!voidPayments[e.id])">{{ busyId===e.id?'Cancelling…':'Confirm cancellation' }}</button><button type="button" class="btn secondary" @click="cancellingId=null">Keep expense</button></div></form>

 <form v-if="payment.expense_id===e.id && e.status==='open'" class="form-grid section-gap" @submit.prevent="payment.transform(d=>({trip_member_id:d.trip_member_id,amount_minor:minor(d.amount),version:d.version})).post(`/trips/${trip.id}/expenses/${e.id}/payments`,{preserveScroll:true,onSuccess:()=>payment.expense_id=0})"><label class="field">Payer<select v-model="payment.trip_member_id"><option v-for="m in trip.members" :key="m.id" :value="m.id">{{ m.user.name }}</option></select></label><label class="field">Amount<input v-model="payment.amount" type="number" min="0.01" step="0.01" required/></label><div class="row full"><button class="btn" :disabled="payment.processing">Save payment</button><button class="btn secondary" type="button" @click="payment.expense_id=0">Cancel</button></div></form>
 </article></section>
 <section v-if="tab==='itinerary'"><div class="row spread"><h2>The plan</h2><span class="muted">Times in {{ trip.timezone }}</span></div><p v-if="!trip.itinerary_items.length" class="card empty section-gap">Your itinerary is a blank canvas.</p><article v-for="item in trip.itinerary_items" :key="item.id" class="card section-gap"><p class="eyebrow">{{ date(item.starts_at) }}</p><h3>{{ item.title }}</h3><p class="row muted"><MapPin :size="14"/><a v-if="item.location" :href="googleMapsUrl(item.location)" target="_blank" rel="noopener noreferrer" style="text-decoration:underline;text-underline-offset:3px">{{ item.location }} ↗</a><span v-else>Location to follow</span></p><p class="muted">Until {{ date(item.ends_at) }}</p></article><form v-if="isOrganizer" class="card form-grid section-gap" @submit.prevent="itinerary.post(`/trips/${trip.id}/itinerary`,{preserveScroll:true,onSuccess:()=>itinerary.reset()})"><h3 class="full">Add to the itinerary</h3><label class="field">Activity<input v-model="itinerary.title" required/></label><label class="field">Location<input v-model="itinerary.location"/></label><label class="field">Starts ({{ trip.timezone }})<input v-model="itinerary.starts_at" type="datetime-local" required/></label><label class="field">Ends<input v-model="itinerary.ends_at" type="datetime-local" required/></label><div class="full"><button class="btn" :disabled="itinerary.processing">Add activity</button></div></form></section>
 <section v-if="tab==='balances'"><h2>Keep it fair.</h2><p class="muted">Completed and closed expenses count here. Reimbursements count once the recipient confirms.</p><div class="card section-gap"><div v-for="b in balances" :key="b.member_id" class="balance-row"><span>{{ b.name }}</span><strong :style="{color:b.net_minor<0?'#a6573e':'#3d7650'}">{{ b.net_minor>0?'Receives':b.net_minor<0?'Owes':'Settled' }} {{ money(Math.abs(b.net_minor)) }}</strong></div></div><form v-if="trip.members.length>1" class="card form-grid section-gap" @submit.prevent="settlement.transform(d=>({to_member_id:d.to_member_id,amount_minor:minor(d.amount),payment_method:d.payment_method})).post(`/trips/${trip.id}/settlements`,{preserveScroll:true,onSuccess:()=>settlement.reset()})"><h3 class="full">Record money you sent</h3><label class="field">Recipient<select v-model="settlement.to_member_id"><option v-for="m in trip.members.filter(m=>m.id!==currentMemberId)" :key="m.id" :value="m.id">{{ m.user.name }}</option></select></label><label class="field">Amount<input v-model="settlement.amount" type="number" min="0.01" step="0.01" required/></label><label class="field">Payment method<select v-model="settlement.payment_method"><option v-for="method in ['gcash','cash','bank_transfer','other']" :key="method">{{ method }}</option></select></label><div class="full"><button class="btn" :disabled="settlement.processing">Record reimbursement</button></div></form><article v-for="s in trip.settlements" :key="s.id" class="card section-gap row spread"><p>{{ name(s.from_member_id) }} → {{ name(s.to_member_id) }} <strong>{{ money(s.amount_minor) }}</strong> <span class="badge">{{ s.status }}</span></p><button v-if="s.status==='pending'&&s.to_member_id===currentMemberId" class="btn" @click="router.post(`/trips/${trip.id}/settlements/${s.id}/confirm`,{},{preserveScroll:true})">Confirm received</button></article></section>
</TravelLayout>
</template>
